   "titulo": "Lobos con piel de oveja: el libro que revela los presuntos vínculos entre miembros de La Luz del Mundo y el crimen organizado",
   "resumen": "Editorial Planeta adelanta un fragmento de uno de los capítulos de ‘Lobos con piel de oveja’, el libro del periodista Isaías Alvarado, que documenta la corrupción y los abusos sexuales cometidos en el seno de la iglesia La Luz del Mundo",
